use termrock::{input::*, interaction::*, runtime::*, style::*, widgets::*};

// Exact paint setup used by the shared catalog story.
fn field_row_states_story(frame: &mut Frame<'_>, area: Rect, system: &DesignSystem) {
    use termrock::widgets::{FieldRow, FieldRowValue};
    let rows = Layout::vertical([Constraint::Length(1); 5]).split(area);
    let labels = ["Workspace", "API token", "Endpoint", "Mode", "Owner"];
    let label_cols = FieldRow::label_cols_for(labels.into_iter());
    FieldRow::new(system, labels[0], FieldRowValue::Plain("termrock"))
        .label_cols(label_cols)
        .marker("◆")
        .paint(rows[0], frame.buffer_mut());
    FieldRow::new(system, labels[1], FieldRowValue::Masked { len: 8 })
        .label_cols(label_cols)
        .annotation("stored locally")
        .annotation_italic(true)
        .paint(rows[1], frame.buffer_mut());
    FieldRow::new(system, labels[2], FieldRowValue::Unset { hint: "required" })
        .label_cols(label_cols)
        .required(true)
        .paint(rows[2], frame.buffer_mut());
    FieldRow::new(system, labels[3], FieldRowValue::Plain("Focused"))
        .label_cols(label_cols)
        .selected(true)
        .paint(rows[3], frame.buffer_mut());
    FieldRow::new(system, labels[4], FieldRowValue::Plain("Tailrocks"))
        .label_cols(label_cols)
        .hovered(true)
        .paint(rows[4], frame.buffer_mut());
}

file-manager/basic:
// Exact long-lived shared demo for file-manager/basic.
// It calls only public termrock::patterns and termrock::widgets APIs;
// host-owned effects are represented by visible typed outcomes.
struct FileManagerDemo {
    state: FileManagerState,
    theme: RolePalette,
    outcome: Option<String>,
}

impl FileManagerDemo {
    fn new() -> Self {
        let mut state = FileManagerState::new();
        state.cwd = "/project".into();
        Self {
            state,
            theme: RolePalette::default(),
            outcome: None,
        }
    }

    fn apply(&mut self, value: FileManagerOutcome) -> bool {
        if matches!(value, FileManagerOutcome::Ignored) {
            return false;
        }
        self.outcome = Some(match &value {
            FileManagerOutcome::OpenRequested { id } => {
                format!("Open requested for {id}; demo did not touch the filesystem")
            }
            FileManagerOutcome::FilterChanged { query } => format!("File filter: {query}"),
            FileManagerOutcome::Toggle { id } => format!("Toggled tree node {id}"),
            FileManagerOutcome::ConfirmDestructive { paths } => {
                format!("Confirmation opened for {} sample path(s)", paths.len())
            }
            FileManagerOutcome::ConfirmCancelled => "File action cancelled".into(),
            other => format!("File manager: {other:?}"),
        });
        true
    }
}

impl StoryInteraction for FileManagerDemo {
    fn render(&mut self, frame: &mut Frame<'_>, area: Rect) {
        let system = crate::design::lookbook_system(self.theme.clone());
        let entries = example_file_entries();
        let ops = example_file_ops();
        let (preview, _, _) = example_file_preview();
        let quick_open = example_quick_open_from_entries(&entries);
        render_file_manager(
            frame.buffer_mut(),
            area,
            FileManagerSurfaces {
                system: &system,
                state: &mut self.state,
                entries: &entries,
                ops: &ops,
                preview: Some(preview),
                quick_open_items: &quick_open,
            },
        );
    }

    fn handle_key(&mut self, key: KeyEvent) -> bool {
        let entries = example_file_entries();
        let ops = example_file_ops();
        let quick_open = example_quick_open_from_entries(&entries);
        let value = self.state.handle_key(key, &entries, &ops, &quick_open);
        self.apply(value)
    }

    fn handle_mouse(&mut self, _mouse: MouseEvent, _preview_area: Rect) -> bool {
        false
    }

    fn set_theme(&mut self, theme: RolePalette) {
        self.theme = theme;
    }

    fn hints(&self) -> Vec<&'static str> {
        vec![
            "↑↓ navigate tree",
            "←→ collapse/expand",
            "Enter open",
            "/ filter",
            "Ctrl+P quick open",
            "Tab panes",
        ]
    }

    fn take_outcome(&mut self) -> Option<String> {
        self.outcome.take()
    }

    fn captures_text_input(&self) -> bool {
        true
    }
}

