use ratatui::prelude::*;
use termrock::{input::*, interaction::*, runtime::*, style::*, widgets::*};

// Exact paint setup used by the selected catalog variant.
fn hint_bar(frame: &mut Frame<'_>, area: Rect, system: &DesignSystem) {
    // The story paints the palette it is documenting: blanking the four Hint
    // roles under phosphor meant the hint ladder never appeared in its own
    // preview (plans/011 Step 2).
    let system = system.clone();
    let hints = [
        Hint {
            chord: "↑↓",
            label: "navigate",
            priority: 1,
            visible: true,
        },
        Hint {
            chord: "Enter",
            label: "choose",
            priority: 1,
            visible: true,
        },
        Hint {
            chord: "Esc",
            label: "close",
            priority: 2,
            visible: true,
        },
    ];
    let bar = HintBar::new(&hints, &system)
        .separator("  ")
        .leading_spacer(true);
    let narrow_bar = HintBar::new(&hints, &system).separator("  ");
    if area.height > 0 {
        frame.buffer_mut().set_stringn(
            area.x,
            area.y,
            format!("WIDE BUDGET  ·  {} ROWS", bar.measured_height(area.width)),
            usize::from(area.width),
            system.style(Role::TextMuted),
        );
    }
    let wide_y = area.y.saturating_add(1);
    let wide_height = bar
        .measured_height(area.width)
        .min(area.bottom().saturating_sub(wide_y));
    frame.render_widget(&bar, Rect::new(area.x, wide_y, area.width, wide_height));

    let narrow_width = area.width.min(20);
    let narrow_y = wide_y.saturating_add(wide_height).saturating_add(1);
    if narrow_y < area.bottom() {
        frame.buffer_mut().set_stringn(
            area.x,
            narrow_y,
            format!(
                "NARROW 20 COL  ·  {} ROWS",
                narrow_bar.measured_height(narrow_width)
            ),
            usize::from(area.width),
            system.style(Role::TextMuted),
        );
    }
    let narrow_bar_y = narrow_y.saturating_add(1);
    frame.render_widget(
        &narrow_bar,
        Rect::new(
            area.x,
            narrow_bar_y,
            narrow_width,
            narrow_bar
                .measured_height(narrow_width)
                .min(area.bottom().saturating_sub(narrow_bar_y)),
        ),
    );
}

