icon/ascii:
use ratatui::prelude::*;
use termrock::{input::*, interaction::*, runtime::*, style::*, widgets::*};

// Exact paint setup used by the selected catalog variant.
fn icon_ascii_story(frame: &mut Frame<'_>, area: Rect, system: &DesignSystem) {
    use termrock::style::{Glyph, GlyphSet, Role};
    use termrock::widgets::Icon;
    let ascii = system.clone().glyphs(GlyphSet::Ascii);
    let samples = [
        Glyph::DisclosureClosed,
        Glyph::DisclosureOpen,
        Glyph::CheckOn,
        Glyph::CheckOff,
        Glyph::Success,
        Glyph::Error,
        Glyph::Ellipsis,
        Glyph::Bullet,
    ];
    let mut y = area.y;
    for g in samples {
        if y >= area.bottom() {
            break;
        }
        let r = g.resolve(GlyphSet::Ascii);
        let line = format!("{} {} — {}", r.text, g.id(), g.meaning());
        frame.buffer_mut().set_stringn(
            area.x,
            y,
            &line,
            usize::from(area.width),
            ascii.style(Role::Text),
        );
        let _ = Icon::new(g, &ascii);
        y = y.saturating_add(1);
    }
}

icon/browser:
use ratatui::prelude::*;
use termrock::{input::*, interaction::*, runtime::*, style::*, widgets::*};

// Exact paint setup used by the shared catalog story.
fn icon_browser_story(frame: &mut Frame<'_>, area: Rect, system: &DesignSystem) {
    use termrock::style::{Glyph, GlyphGroup, Role};
    use termrock::widgets::Icon;
    let mut y = area.y;
    for group in GlyphGroup::ALL {
        if y >= area.bottom() {
            break;
        }
        frame.buffer_mut().set_stringn(
            area.x,
            y,
            group.id(),
            usize::from(area.width),
            system.style(Role::TextMuted),
        );
        y = y.saturating_add(1);
        let mut x = area.x;
        for g in Glyph::in_group(group) {
            if y >= area.bottom() {
                break;
            }
            let w = 4u16;
            if x.saturating_add(w) > area.right() {
                x = area.x;
                y = y.saturating_add(1);
                if y >= area.bottom() {
                    break;
                }
            }
            let _ = Icon::new(g, system).min_width(w).paint(
                Rect {
                    x,
                    y,
                    width: w,
                    height: 1,
                },
                frame.buffer_mut(),
            );
            x = x.saturating_add(w);
        }
        y = y.saturating_add(1);
    }
}

