        let row = Rect::new(
            area.x,
            y,
            area.width,
            h.min(area.bottom().saturating_sub(y)),
        );
        let body =
            Panel::new(system)
                .title(v.id())
                .variant(*v)
                .paint(row, frame.buffer_mut(), None);
        if body.width > 2 && body.height > 0 {
            frame.buffer_mut().set_stringn(
                body.x,
                body.y,
                v.id(),
                usize::from(body.width),
                system.style(Role::TextMuted),
            );
        }
    }
}

