            status: None,
            badge: None,
            shortcut: None,
            actions: None,
            trailing: None,
            custom: None,
            role: RowRole::Item,
            enabled: true,
            loading: false,
        },
        ListRow {
            id: "b",
            label: Line::from("Beta"),
            leading: None,
            secondary: None,
            status: None,
            badge: None,
            shortcut: None,
            actions: None,
            trailing: None,
            custom: None,
            role: RowRole::Item,
            enabled: true,
            loading: false,
        },
        ListRow {
            id: "c",
            label: Line::from("Gamma"),
            leading: None,
            secondary: None,
            status: None,
            badge: None,
            shortcut: None,
            actions: None,
            trailing: None,
            custom: None,
            role: RowRole::Item,
            enabled: true,
            loading: false,
        },
    ];
    let mut state = ListState::new(Some("a"));
    state.enable_multi_select();
    if let Some(sel) = state.selection_mut() {
        let _ = sel.toggle(&"a");
        let _ = sel.toggle(&"c");
    }
    let visual = SelectionVisual::from_chrome(SelectionChrome::Gutter);
    frame.render_widget(
        Panel::new(system)
            .title(if visual.requires_glyph() {
                "SelectionModel (gutter+check)"
            } else {
                "SelectionModel"
            })
            .chrome(PanelChrome::Focused),
        area,
    );
    let inner = Rect::new(
        area.x.saturating_add(1),
        area.y.saturating_add(1),
        area.width.saturating_sub(2),
        area.height.saturating_sub(2),
    );
    frame.render_stateful_widget(List::new(&rows, system).focused(true), inner, &mut state);
    let _ = SelectionModel::<&str>::multiple();
}

