use ratatui::prelude::*;
use termrock::{input::*, interaction::*, runtime::*, style::*, widgets::*};

// Exact paint setup used by the selected catalog variant.
fn text_spans_story(frame: &mut Frame<'_>, area: Rect, system: &DesignSystem) {
    use termrock::style::Role;
    use termrock::widgets::{Text, TextSpan};
    let chunks = Layout::vertical([
        Constraint::Length(1),
        Constraint::Length(1),
        Constraint::Min(1),
    ])
    .split(area);
    let _ = Text::spans(
        [
            TextSpan::new("Status: ").role(Role::TextMuted),
            TextSpan::new("READY").role(Role::Success).strong(),
            TextSpan::new(" · ").dim(),
            TextSpan::new("cached")
                .role(Role::TextMuted)
                .annotation("meta"),
        ],
        system,
    )
    .paint(chunks[0], frame.buffer_mut());
    let _ = Text::spans(
        [
            TextSpan::new("Search hit: "),
            TextSpan::new("termrock")
                .highlight(true)
                .annotation("search"),
